  s.season = 2; s.school.stars = 64; s.school.name = 'Les Étoiles';
  s.plan.order = ['accueil', 'G1', 'M1', 'P1', 'entracte', 'P2', 'M2', 'G2', 'final'];
  s.plan.numbers.G1.A[0] = { x: -4, z: 2 };
