47	  if (G.run) { toast(t().gs.notNow); return; }
48	  if (!gateEl) { gateEl = document.createElement('div'); gateEl.id = 'gate'; document.body.appendChild(gateEl); }
49	  const ask = (msg = '') => {
50	    const a = rnd(12, 19), b = rnd(3, 9), T = t().gs;
51	    gateEl.innerHTML = `<div class="box" role="dialog" aria-modal="true" aria-labelledby="gateH"><h2 id="gateH">${esc(T.gateH)}</h2><p id="gateQ">${esc(T.gateQ(a, b))}</p>`
52	      + `<input type="text" id="gateIn" inputmode="numeric" maxlength="4" autocomplete="off" aria-labelledby="gateQ"><p class="hint warn" id="gateMsg">${esc(msg)}</p>`
53	      + `<div class="chips"><button type="button" class="big" id="gateOk">${esc(T.ok)}</button><button type="button" id="gateNo">${esc(T.cancel)}</button></div></div>`;
54	    gateEl.hidden = false;
55	    const inp = gateEl.querySelector('#gateIn'), shut = () => { gateEl.hidden = true; };
56	    const go = () => { if (inp.value.trim() === String(a * b)) { shut(); openSettings(); } else ask(T.gateNo); };
57	    gateEl.querySelector('#gateOk').onclick = go; gateEl.querySelector('#gateNo').onclick = shut;
58	    inp.onkeydown = (e) => { if (e.key === 'Enter') go(); if (e.key === 'Escape') shut(); };
59	    inp.focus();
60	  };
61	  ask();
62	}
63	
64	/* ---------------- the screen ---------------- */
65	let panel = null;
66	export function openSettings() {
67	  if (!panel) { panel = document.createElement('div'); panel.id = 'grown'; document.body.appendChild(panel); }
68	  panel.hidden = false; GS.msg = null; GS.status = GS.reached ? '' : t().gs.offline; render();
69	}
70	export async function closeSettings() {
71	  if (!panel) return;
72	  if (!GS.dirty) { panel.hidden = true; return; }
73	  await flush();
74	  try { sessionStorage.setItem(APPLIED_KEY, '1'); } catch { /* storage blocked */ }
75	  location.reload();
76	}
77	const TABS = ['moves', 'outfits', 'shop', 'school', 'file'];
78	function render() {
79	  const T = t().gs, body = panel.querySelector('.gbody'), top = body ? body.scrollTop : 0;
80	  // the rows open now stay open (read here: the toggle event can come after a quick Enter)
81	  for (const d of panel.querySelectorAll('details[data-row]')) if (d.open) GS.openRows.add(d.dataset.row); else GS.openRows.delete(d.dataset.row);
82	  panel.innerHTML = `<div class="gpanel" role="dialog" aria-modal="true" aria-labelledby="gTitle"><div class="ghead"><h2 id="gTitle">${esc(T.title)}</h2>`
83	    + `<button type="button" class="small" id="gLang">${esc(t().lang)}</button><button type="button" class="gclose" id="gClose">${esc(T.close)}</button></div>`
84	    + `<p class="hint">${esc(T.intro)}</p><nav class="chips gtabs">${TABS.map((k) => `<button type="button" data-gtab="${k}" aria-pressed="${GS.tab === k}">${esc(T.tabs[k])}</button>`).join('')}</nav>`
85	    + `<div class="gbody">${({ moves: () => rowsOf('moves'), outfits: () => rowsOf('outfits'), shop: shopTab, school: schoolTab, file: fileTab })[GS.tab]()}</div>`
86	    + `<div class="gstatus" id="gStatus" role="status">${esc(GS.status)}</div></div>`;
87	  panel.querySelector('.gbody').scrollTop = top;
88	  bind();
89	}
90	const nameOf = (table, id) => valueOf(GS.file, table, id, G.lang) || valueOf(GS.file, table, id, 'fr') || id;
91	const iconOf = (table, id) => valueOf(GS.file, table, id, 'icon') || '';
92	const isChanged = (table, id) => table === 'names' ? !!GS.file.rows.names?.[id] : !!GS.file.rows[table]?.[id];
93	// one row: its name, and its fields when opened
94	function rowBlock(table, id, extra = '') {
95	  const key = `${table}|${id}`, mine = isNewId(id), T = t().gs;
96	  let h = `<details class="grow" data-row="${esc(key)}"${GS.openRows.has(key) ? ' open' : ''}><summary><span class="ic">${esc(iconOf(table, id))}</span> ${esc(nameOf(table, id))}`
97	    + `${mine ? ` <small class="mine">${esc(T.mine)}</small>` : isChanged(table, id) ? ` <small class="chg">● ${esc(T.changed)}</small>` : ''}</summary><div class="gfields">`;
98	  for (const [f, spec] of Object.entries(fieldsOf(table, id))) h += field(table, id, f, spec);
99	  if (mine) h += `<button type="button" class="small" data-del="${esc(key)}">${esc(T.remove)}</button>`;
100	  return `${h}${extra}</div></details>`;
101	}
102	function rowsOf(table) {
103	  const T = t().gs, ids = [...newIds(GS.file, table), ...Object.keys(DEFAULTS[table])];
104	  return `<div class="chips"><button type="button" class="big" data-add="${table}">${esc(table === 'moves' ? T.addMove : T.addOutfit)}</button></div>${ids.map((id) => rowBlock(table, id)).join('')}`;
105	}
106	function shopTab() {
107	  return ['hairs', 'shoes', 'accs', 'pieces', 'snacks', 'upgrades'].map((table) => `<h3>${esc(t().gs.shopH[table])}</h3>${Object.keys(DEFAULTS[table]).map((id) => rowBlock(table, id)).join('')}`).join('');
108	}
109	function schoolTab() {
110	  const T = t().gs, stars = valueOf(GS.file, 'start', 'start', 'stars');
111	  let h = `<h3>${esc(T.startH)}</h3>${field('start', 'start', 'stars', SCHEMA.start.fields.stars)}<div class="chips"><button type="button" id="gNewSchool">${esc(T.newSchool(stars))}</button></div>`;
112	  h += `<h3>${esc(T.classesH)}</h3>${Object.keys(DEFAULTS.classes).map((id) => rowBlock('classes', id)).join('')}`;
113	  h += `<h3>${esc(T.numbersH)}</h3>${Object.keys(DEFAULTS.numbers).map((id) => rowBlock('numbers', id)).join('')}`;
114	  h += `<h3>${esc(T.namesH)}</h3>`;
115	  for (const cls of Object.keys(DEFAULTS.names)) {
116	    const key = `names|${cls}`;
117	    h += `<details class="grow" data-row="${esc(key)}"${GS.openRows.has(key) ? ' open' : ''}><summary>${esc(nameOf('classes', cls))}${isChanged('names', cls) ? ` <small class="chg">● ${esc(T.changed)}</small>` : ''}</summary><div class="gfields">`
118	      + DEFAULTS.names[cls].map((_, i) => field('names', cls, i, SCHEMA.names.list, `${i + 1}`)).join('') + '</div></details>';
119	  }
120	  return h;
121	}
122	function fileTab() {
123	  const T = t().gs;
124	  return `<h3>${esc(T.fileH)}</h3><p class="hint">${esc(T.fileHint)}</p><div class="chips"><button type="button" id="gSaveFile">${esc(T.saveFile)}</button>`
125	    + `<button type="button" id="gLoadFile">${esc(T.loadFile)}</button><input type="file" id="gFile" accept=".json,application/json" hidden></div>`
126	    + `<h3>${esc(T.allDefault)}</h3><div class="chips"><button type="button" id="gAllDefault">↺ ${esc(T.allDefault)}</button></div>`;
127	}
128	
129	/* ---------------- one field ---------------- */
130	const LEVEL_ICON = ['⬇', '➖', '⬆'];
131	function field(table, id, f, spec, label) {
132	  const T = t().gs, key = `${table}|${id}|${f}`, v = valueOf(GS.file, table, id, f), def = table === 'names' ? DEFAULTS.names[id][f] : isNewId(id) ? undefined : DEFAULTS[table][id]?.[f];
133	  const name = label ?? (f === 'min' && table === 'hairs' ? T.f.minHair : T.f[f]), at = { 'data-t': table, 'data-id': id, 'data-f': f };
134	  const attrs = Object.entries(at).map(([k, x]) => `${k}="${esc(x)}"`).join(' ');
135	  const same = isNewId(id) ? !GS.file.rows[table]?.[id] : JSON.stringify(v) === JSON.stringify(def);
136	  const back = `<button type="button" class="gdef" data-def ${attrs} title="${esc(T.defTip)}" aria-label="${esc(T.defTip)} (${esc(name)})"${same ? ' disabled' : ''}>${T.def}</button>`;
137	  const msg = GS.msg && GS.msg.key === key ? `<span class="gmsg" role="alert">${esc(GS.msg.text)}</span>` : '';
138	  let input;
139	  if (spec.kind === 'text') input = `<input type="text" data-k="text" ${attrs} maxlength="${spec.max}" value="${esc(v ?? '')}" aria-label="${esc(name)}">`;
140	  else if (spec.kind === 'int' && spec.max - spec.min <= 2) {
141	    const lab = (n) => (f === 'd' ? '●'.repeat(n) + '○'.repeat(3 - n) : f === 'a' || f === 'b' ? `${LEVEL_ICON[n]} ${T.levels[n]}` : String(n));
142	    input = `<span class="chips">${Array.from({ length: spec.max - spec.min + 1 }, (_, k) => spec.min + k).map((n) => `<button type="button" data-k="set" ${attrs} data-v="${n}" aria-pressed="${v === n}">${esc(lab(n))}</button>`).join('')}</span>`;
143	  } else if (spec.kind === 'int') input = `<span class="gnum"><button type="button" data-k="step" ${attrs} data-d="-1" aria-label="−">−</button><input type="text" data-k="int" ${attrs} inputmode="numeric" maxlength="${String(spec.max).length + 1}" value="${esc(v ?? '')}" aria-label="${esc(name)}"><button type="button" data-k="step" ${attrs} data-d="1" aria-label="+">+</button></span>`;
144	  else if (f === 'icon') input = `<span class="gicons">${ICONS.map((ic) => `<button type="button" data-k="set" ${attrs} data-v="${esc(ic)}" aria-pressed="${v === ic}">${esc(ic)}</button>`).join('')}</span>`;
145	  else if (f === 'c') input = `<span class="chips">${spec.of.map((n) => `<button type="button" data-k="set" ${attrs} data-v="${n}" aria-pressed="${v === n}">${esc(t().countsShort(n))}</button>`).join('')}</span>`;
146	  else if (spec.kind === 'pick') {
147	    const src = f === 'like' ? MOVES : OUTFITS;
148	    input = `<select data-k="select" ${attrs} aria-label="${esc(name)}">${spec.of.map((k) => `<option value="${esc(k)}"${v === k ? ' selected' : ''}>${esc(`${src[k]?.icon || ''} ${nm(src[k])}`)}</option>`).join('')}</select>`;
149	  } else if (spec.kind === 'styles') {
150	    const on = v === '*' ? [] : String(v || '').split(' ');
151	    input = `<span class="chips"><button type="button" data-k="styles" ${attrs} data-v="*" aria-pressed="${v === '*'}">${esc(T.allStyles)}</button>${Object.entries(STYLES).map(([k, s]) => `<button type="button" data-k="styles" ${attrs} data-v="${k}" aria-pressed="${on.includes(k)}">${s.icon} ${esc(nm(s))}</button>`).join('')}</span>`;
152	  } else if (spec.kind === 'themes') {
153	    const on = Array.isArray(v) ? v : [];
154	    input = `<span class="chips">${THEMES.map((th) => `<button type="button" data-k="themes" ${attrs} data-v="${th}" aria-pressed="${on.includes(th)}">${esc(Object.values(NUMBERS).filter((n) => n.theme === th).map((n) => nm(n)).join(' / '))}</button>`).join('')}</span>`;
155	  }
156	  return `<div class="gf" data-key="${esc(key)}"><span class="gl">${esc(name)}</span><span class="gin">${input}${back}</span>${msg}</div>`;
157	}
158	
159	/* ---------------- what each control does ---------------- */
160	const whyText = (why, table, id, f) => {
161	  const W = t().gs.why, spec = table === 'names' ? SCHEMA.names.list : fieldsOf(table, id)[f] || {};
162	  return why === 'long' ? W.long(spec.max) : why === 'range' ? W.range(spec.min, spec.max) : W[why] || W.field;
163	};
164	const target = (el) => { const id = el.dataset.id, table = el.dataset.t, f = table === 'names' ? +el.dataset.f : el.dataset.f; return { table, id, f }; };
165	// a value from a control: stored if valid, otherwise a kind message and nothing changes
166	function setValue(el, value) {
167	  const { table, id, f } = target(el), c = check(table, id, f, value);
168	  if (!c.ok) { GS.msg = { key: `${table}|${id}|${f}`, text: whyText(c.why, table, id, f) }; render(); return false; }
169	  GS.msg = null; commit(withField(GS.file, table, id, f, c.value)); return true;
170	}
171	function commit(next) {
172	  GS.file = sanitize(next).file; GS.dirty = true; keepCopy();
173	  GS.status = t().gs.saved; render();
174	  putFile('settings', GS.file).then((ok) => { GS.status = ok ? t().gs.saved : t().gs.offline; const s = panel && panel.querySelector('#gStatus'); if (s) s.textContent = GS.status; });
175	}
176	function bind() {
177	  const $ = (s) => panel.querySelector(s), all = (s) => panel.querySelectorAll(s), T = t().gs;
178	  $('#gClose').onclick = closeSettings;
179	  $('#gLang').onclick = () => { document.getElementById('langBtn').click(); render(); };
180	  panel.onkeydown = (e) => { if (e.key === 'Escape' && !e.target.matches('input, select')) closeSettings(); };
181	  for (const b of all('[data-gtab]')) b.onclick = () => { GS.tab = b.dataset.gtab; GS.msg = null; render(); panel.querySelector('.gbody').scrollTop = 0; };
182	  for (const d of all('details[data-row]')) d.ontoggle = () => { if (d.open) GS.openRows.add(d.dataset.row); else GS.openRows.delete(d.dataset.row); };
183	  for (const el of all('input[data-k="text"], input[data-k="int"]')) {
184	    el.onchange = () => setValue(el, el.value);
185	    el.onkeydown = (e) => { if (e.key === 'Enter') el.blur(); };
186	  }
187	  for (const el of all('select[data-k="select"]')) el.onchange = () => setValue(el, el.value);
188	  for (const b of all('[data-k="set"]')) b.onclick = () => setValue(b, b.dataset.f === 'icon' ? b.dataset.v : +b.dataset.v);
189	  for (const b of all('[data-k="step"]')) b.onclick = () => {
190	    const { table, id, f } = target(b), spec = fieldsOf(table, id)[f], v = valueOf(GS.file, table, id, f) ?? spec.min;
191	    const n = Math.max(spec.min, Math.min(spec.max, v + +b.dataset.d * (f === 'stars' ? 5 : 1)));
192	    if (n !== v) setValue(b, n);
193	  };
194	  for (const b of all('[data-k="styles"]')) b.onclick = () => {
195	    const { table, id, f } = target(b), v = valueOf(GS.file, table, id, f), k = b.dataset.v;
196	    if (k === '*') { setValue(b, '*'); return; }
197	    const on = new Set(v === '*' ? [] : String(v).split(' ').filter(Boolean)); if (on.has(k)) on.delete(k); else on.add(k);
198	    setValue(b, on.size ? [...on].join(' ') : '');
199	  };
200	  for (const b of all('[data-k="themes"]')) b.onclick = () => {
201	    const { table, id, f } = target(b), on = new Set(valueOf(GS.file, table, id, f) || []), k = b.dataset.v;
202	    if (on.has(k)) on.delete(k); else on.add(k); setValue(b, [...on]);
203	  };
204	  for (const b of all('[data-def]')) b.onclick = () => { const { table, id, f } = target(b); GS.msg = null; commit(withField(GS.file, table, id, f, undefined)); };
205	  for (const b of all('[data-add]')) b.onclick = () => {
206	    const table = b.dataset.add, { id, row } = newRow(table, GS.file);
207	    if (!id) { toast(T.maxNew(MAX_NEW)); return; }
208	    const next = copy(GS.file); next.rows[table] = { ...(next.rows[table] || {}), [id]: row };
209	    GS.openRows.add(`${table}|${id}`); commit(next);
210	  };
211	  for (const b of all('[data-del]')) b.onclick = () => {
212	    const [table, id] = b.dataset.del.split('|');
213	    if (!confirm(T.removeAsk(nameOf(table, id)))) return;
214	    const next = copy(GS.file); delete next.rows[table][id]; if (!Object.keys(next.rows[table]).length) delete next.rows[table];
215	    commit(next);
216	  };
217	  const ns = $('#gNewSchool');
218	  if (ns) ns.onclick = () => {
219	    const stars = valueOf(GS.file, 'start', 'start', 'stars');
220	    if (!confirm(T.newSchoolAsk(stars))) return;
221	    START.stars = stars; resetAll(); GS.dirty = true; closeSettings();
222	  };
223	  const sf = $('#gSaveFile');
224	  if (sf) sf.onclick = () => {
225	    const url = URL.createObjectURL(new Blob([JSON.stringify(GS.file, null, 2)], { type: 'application/json' })), a = document.createElement('a');
226	    a.href = url; a.download = 'gala-de-danse-reglages.json'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
227	  };
228	  const lf = $('#gLoadFile'), fi = $('#gFile');
229	  if (lf) lf.onclick = () => fi.click();
230	  if (fi) fi.onchange = async () => {
231	    const file = fi.files && fi.files[0]; fi.value = ''; if (!file) return;
232	    if (file.size > MAX_FILE) { toast(T.bigFile); return; }
233	    let obj; try { obj = JSON.parse(await file.text()); } catch { toast(T.badFile); return; }
234	    // a settings file has a version and rows, or (an older one) at least one table the game knows
235	    const isSettings = obj && typeof obj === 'object' && !Array.isArray(obj) && ((obj.v !== undefined && obj.rows) || Object.keys(obj).some((k) => Object.hasOwn(SCHEMA, k)));
236	    if (!isSettings) { toast(T.badFile); return; }
237	    const r = sanitize(obj);
238	    commit(r.file); toast(T.loaded(r.dropped));
239	  };
240	  const ad = $('#gAllDefault');
241	  if (ad) ad.onclick = () => { if (confirm(T.allDefaultAsk)) commit({ v: 1, rows: {} }); };
242	}
